InfGen.PY = {"linear": [{"lv": 1, "title": "Приветствие", "t": "Программа читает имя и выводит «Привет, <имя>!».", "start": "name = input()\n# Напишите решение под этой строкой\n", "sol": "name = input()\nprint(\"Привет, \" + name + \"!\")", "tests": [["Аня", "Привет, Аня!"], ["Максим", "Привет, Максим!"]]}, {"lv": 1, "title": "Площадь прямоугольника", "t": "Вводятся длины сторон a и b (каждая в своей строке). Выведите площадь.", "start": "a = int(input())\nb = int(input())\n# Напишите решение под этой строкой\n", "sol": "a = int(input())\nb = int(input())\nprint(a * b)", "tests": [["3\n4", "12"], ["10\n25", "250"], ["7\n7", "49"]]}, {"lv": 2, "title": "Сдача", "t": "Цена одной тетради, количество тетрадей, внесённая сумма (по строкам). Выведите сдачу.", "start": "price = int(input())\nk = int(input())\nmoney = int(input())\n# Напишите решение под этой строкой\n", "sol": "price = int(input())\nk = int(input())\nmoney = int(input())\nprint(money - price * k)", "tests": [["30\n4\n200", "80"], ["45\n2\n100", "10"], ["12\n10\n120", "0"]]}, {"lv": 2, "title": "Время в пути", "t": "Расстояние s (км) и скорость v (км/ч) — по строкам. Выведите время в пути в минутах (целая часть).", "start": "s = int(input())\nv = int(input())\n# Напишите решение под этой строкой\n", "sol": "s = int(input())\nv = int(input())\nprint(s * 60 // v)", "tests": [["120\n60", "120"], ["100\n40", "150"], ["45\n50", "54"]]}, {"lv": 2, "title": "Сумма цифр двузначного числа", "t": "Введено двузначное число. Выведите сумму его цифр (операции // и %).", "start": "n = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nprint(n // 10 + n % 10)", "tests": [["47", "11"], ["90", "9"], ["99", "18"]]}, {"lv": 3, "title": "Чётное ли число?", "t": "Введите целое число. Выведите True, если оно чётное, и False, если нет (логическое выражение, без if).", "start": "n = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nprint(n % 2 == 0)", "tests": [["10", "True"], ["7", "False"], ["0", "True"]]}], "cond": [{"lv": 1, "title": "Большее из двух", "t": "Введены два числа (по строкам). Выведите большее.", "start": "a = int(input())\nb = int(input())\n# Напишите решение под этой строкой\n", "sol": "a = int(input())\nb = int(input())\nif a > b:\n    print(a)\nelse:\n    print(b)", "tests": [["3\n8", "8"], ["9\n2", "9"], ["5\n5", "5"]]}, {"lv": 1, "title": "Знак числа", "t": "Выведите слово «положительное», «отрицательное» или «ноль».", "start": "n = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nif n > 0:\n    print(\"положительное\")\nelif n < 0:\n    print(\"отрицательное\")\nelse:\n    print(\"ноль\")", "tests": [["5", "положительное"], ["-3", "отрицательное"], ["0", "ноль"]]}, {"lv": 2, "title": "Существует ли треугольник", "t": "Даны три стороны (по строкам). Выведите «да», если треугольник существует (каждая сторона меньше суммы двух других), иначе «нет».", "start": "a = int(input())\nb = int(input())\nc = int(input())\n# Напишите решение под этой строкой\n", "sol": "a = int(input())\nb = int(input())\nc = int(input())\nif a < b + c and b < a + c and c < a + b:\n    print(\"да\")\nelse:\n    print(\"нет\")", "tests": [["3\n4\n5", "да"], ["1\n2\n3", "нет"], ["10\n6\n5", "да"], ["2\n2\n4", "нет"]]}, {"lv": 2, "title": "Отметка", "t": "Введены баллы за работу (0–100). Выведите отметку: от 85 — 5, от 70 — 4, от 50 — 3, иначе 2.", "start": "b = int(input())\n# Напишите решение под этой строкой\n", "sol": "b = int(input())\nif b >= 85:\n    print(5)\nelif b >= 70:\n    print(4)\nelif b >= 50:\n    print(3)\nelse:\n    print(2)", "tests": [["90", "5"], ["85", "5"], ["70", "4"], ["69", "3"], ["50", "3"], ["10", "2"]]}, {"lv": 3, "title": "Високосный год", "t": "Выведите «високосный» или «обычный». Год високосный, если делится на 4 и не делится на 100, либо делится на 400.", "start": "year = int(input())\n# Напишите решение под этой строкой\n", "sol": "y = int(input())\nif y % 4 == 0 and y % 100 != 0 or y % 400 == 0:\n    print(\"високосный\")\nelse:\n    print(\"обычный\")", "tests": [["2024", "високосный"], ["1900", "обычный"], ["2000", "високосный"], ["2023", "обычный"]]}], "for": [{"lv": 1, "title": "Сумма от 1 до n", "t": "Введено n. Выведите сумму 1 + 2 + … + n.", "start": "n = int(input())\ns = 0\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\ns = 0\nfor i in range(1, n + 1):\n    s += i\nprint(s)", "tests": [["5", "15"], ["100", "5050"], ["1", "1"]]}, {"lv": 1, "title": "Таблица умножения", "t": "Введено n. Выведите 10 строк вида «3 x 1 = 3».", "start": "n = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nfor i in range(1, 11):\n    print(n, \"x\", i, \"=\", n * i)", "tests": [["3", "3 x 1 = 3\n3 x 2 = 6\n3 x 3 = 9\n3 x 4 = 12\n3 x 5 = 15\n3 x 6 = 18\n3 x 7 = 21\n3 x 8 = 24\n3 x 9 = 27\n3 x 10 = 30"], ["7", "7 x 1 = 7\n7 x 2 = 14\n7 x 3 = 21\n7 x 4 = 28\n7 x 5 = 35\n7 x 6 = 42\n7 x 7 = 49\n7 x 8 = 56\n7 x 9 = 63\n7 x 10 = 70"]]}, {"lv": 2, "title": "Чётные среди n чисел", "t": "Сначала вводится n, затем n чисел (каждое в своей строке). Выведите, сколько среди них чётных.", "start": "n = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nk = 0\nfor i in range(n):\n    x = int(input())\n    if x % 2 == 0:\n        k += 1\nprint(k)", "tests": [["4\n1\n2\n3\n4", "2"], ["3\n5\n7\n9", "0"], ["5\n2\n4\n6\n8\n10", "5"]]}, {"lv": 2, "title": "Лесенка", "t": "Введено n. Выведите n строк: в строке с номером i — i звёздочек.", "start": "n = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nfor i in range(1, n + 1):\n    print(\"*\" * i)", "tests": [["3", "*\n**\n***"], ["5", "*\n**\n***\n****\n*****"]]}, {"lv": 3, "title": "Факториал", "t": "Введено n. Выведите n! = 1·2·…·n.", "start": "n = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nf = 1\nfor i in range(2, n + 1):\n    f *= i\nprint(f)", "tests": [["5", "120"], ["1", "1"], ["10", "3628800"]]}], "while": [{"lv": 1, "title": "Сумма цифр числа", "t": "Введено натуральное число. Выведите сумму его цифр (цикл while).", "start": "n = int(input())\ns = 0\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\ns = 0\nwhile n > 0:\n    s += n % 10\n    n //= 10\nprint(s)", "tests": [["123", "6"], ["9999", "36"], ["1000", "1"], ["7", "7"]]}, {"lv": 2, "title": "Сколько цифр в числе", "t": "Введено натуральное число. Выведите количество цифр (без str и len).", "start": "n = int(input())\nk = 0\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nk = 0\nwhile n > 0:\n    k += 1\n    n //= 10\nprint(k)", "tests": [["5", "1"], ["100", "3"], ["123456", "6"]]}, {"lv": 2, "title": "Удвоение", "t": "Вклад 1 рубль удваивается каждый день. Введено число m. Выведите, через сколько дней сумма впервые станет не меньше m.", "start": "m = int(input())\ns = 1\nd = 0\n# Напишите решение под этой строкой\n", "sol": "m = int(input())\ns = 1\nd = 0\nwhile s < m:\n    s *= 2\n    d += 1\nprint(d)", "tests": [["1", "0"], ["100", "7"], ["1000", "10"]]}, {"lv": 3, "title": "НОД (алгоритм Евклида)", "t": "Введены два натуральных числа. Выведите их наибольший общий делитель.", "start": "a = int(input())\nb = int(input())\n# Напишите решение под этой строкой\n", "sol": "a = int(input())\nb = int(input())\nwhile b != 0:\n    a, b = b, a % b\nprint(a)", "tests": [["12\n18", "6"], ["17\n5", "1"], ["100\n75", "25"]]}], "arr": [{"lv": 1, "title": "Сумма элементов", "t": "Сначала n, затем n чисел в одной строке. Выведите их сумму.", "start": "n = int(input())\na = list(map(int, input().split()))\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\na = list(map(int, input().split()))\ns = 0\nfor x in a:\n    s += x\nprint(s)", "tests": [["3\n1 2 3", "6"], ["5\n10 20 30 40 50", "150"], ["1\n7", "7"]]}, {"lv": 2, "title": "Максимум и его номер", "t": "Выведите наибольший элемент и номер его первого вхождения (нумерация с 0) через пробел.", "start": "n = int(input())\na = list(map(int, input().split()))\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\na = list(map(int, input().split()))\nm = a[0]\nk = 0\nfor i in range(n):\n    if a[i] > m:\n        m = a[i]\n        k = i\nprint(m, k)", "tests": [["4\n5 7 2 7", "7 1"], ["3\n9 1 1", "9 0"], ["1\n4", "4 0"]]}, {"lv": 2, "title": "Больше среднего", "t": "Выведите, сколько элементов больше среднего арифметического.", "start": "n = int(input())\na = list(map(int, input().split()))\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\na = list(map(int, input().split()))\navg = sum(a) / n\nk = 0\nfor x in a:\n    if x > avg:\n        k += 1\nprint(k)", "tests": [["4\n1 2 3 4", "2"], ["3\n5 5 5", "0"], ["5\n1 1 1 1 10", "1"]]}, {"lv": 2, "title": "Наоборот", "t": "Выведите элементы в обратном порядке через пробел.", "start": "n = int(input())\na = list(map(int, input().split()))\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\na = list(map(int, input().split()))\nprint(*a[::-1])", "tests": [["3\n1 2 3", "3 2 1"], ["4\n5 0 -1 8", "8 -1 0 5"]]}, {"lv": 3, "title": "Поиск", "t": "Вводятся n, список, затем число x. Выведите номер первого элемента, равного x (с 0), или -1.", "start": "n = int(input())\na = list(map(int, input().split()))\nx = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\na = list(map(int, input().split()))\nx = int(input())\nk = -1\nfor i in range(n):\n    if a[i] == x:\n        k = i\n        break\nprint(k)", "tests": [["4\n5 7 2 7\n7", "1"], ["3\n1 2 3\n9", "-1"]]}], "sort": [{"lv": 2, "title": "Сортировка пузырьком", "t": "Отсортируйте список по возрастанию «пузырьком» (двумя вложенными циклами, без sort) и выведите через пробел.", "start": "n = int(input())\na = list(map(int, input().split()))\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\na = list(map(int, input().split()))\nfor i in range(n - 1):\n    for j in range(n - 1 - i):\n        if a[j] > a[j + 1]:\n            a[j], a[j + 1] = a[j + 1], a[j]\nprint(*a)", "tests": [["5\n5 2 9 1 3", "1 2 3 5 9"], ["3\n1 2 3", "1 2 3"], ["4\n4 3 2 1", "1 2 3 4"]]}, {"lv": 3, "title": "Сортировка выбором", "t": "Отсортируйте список по возрастанию методом выбора минимума и выведите через пробел.", "start": "n = int(input())\na = list(map(int, input().split()))\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\na = list(map(int, input().split()))\nfor i in range(n - 1):\n    k = i\n    for j in range(i + 1, n):\n        if a[j] < a[k]:\n            k = j\n    a[i], a[k] = a[k], a[i]\nprint(*a)", "tests": [["5\n5 2 9 1 3", "1 2 3 5 9"], ["2\n2 1", "1 2"]]}], "str": [{"lv": 1, "title": "Сколько гласных", "t": "Введена строка маленькими русскими буквами. Выведите количество гласных (а е ё и о у ы э ю я).", "start": "s = input()\n# Напишите решение под этой строкой\n", "sol": "s = input()\nk = 0\nfor c in s:\n    if c in \"аеёиоуыэюя\":\n        k += 1\nprint(k)", "tests": [["привет мир", "3"], ["кот", "1"], ["сплтн", "0"]]}, {"lv": 2, "title": "Слова", "t": "Введено предложение. Выведите, сколько в нём слов.", "start": "s = input()\n# Напишите решение под этой строкой\n", "sol": "s = input()\nprint(len(s.split()))", "tests": [["мама мыла раму", "3"], ["один", "1"], ["а б в г д", "5"]]}, {"lv": 2, "title": "Палиндром", "t": "Выведите «да», если строка (без пробелов) читается одинаково в обе стороны, иначе «нет».", "start": "s = input()\n# Напишите решение под этой строкой\n", "sol": "s = input().replace(\" \", \"\")\nif s == s[::-1]:\n    print(\"да\")\nelse:\n    print(\"нет\")", "tests": [["топот", "да"], ["а роза упала на лапу азора", "да"], ["python", "нет"]]}, {"lv": 3, "title": "Шифр Цезаря", "t": "Вводятся строка из маленьких латинских букв и сдвиг k. Каждую букву сдвиньте по алфавиту на k вперёд по кругу.", "start": "s = input()\nk = int(input())\n# Напишите решение под этой строкой\n", "sol": "s = input()\nk = int(input())\nr = \"\"\nfor c in s:\n    r += chr((ord(c) - 97 + k) % 26 + 97)\nprint(r)", "tests": [["abc\n1", "bcd"], ["xyz\n3", "abc"], ["hello\n13", "uryyb"]]}], "func": [{"lv": 1, "title": "Функция «квадрат»", "t": "Опишите функцию sq(x), возвращающую x². Прочитайте число и выведите sq(число).", "start": "def sq(x):\n    # допишите\n    pass\n\nn = int(input())\nprint(sq(n))", "sol": "def sq(x):\n    return x * x\n\nn = int(input())\nprint(sq(n))", "tests": [["5", "25"], ["-3", "9"], ["0", "0"]]}, {"lv": 2, "title": "Простое число", "t": "Опишите функцию is_prime(n) (True/False). Выведите «простое» или «составное» (для n ≥ 2).", "start": "def is_prime(n):\n    # допишите\n    pass\n\nn = int(input())\nprint(\"простое\" if is_prime(n) else \"составное\")", "sol": "def is_prime(n):\n    d = 2\n    while d * d <= n:\n        if n % d == 0:\n            return False\n        d += 1\n    return True\n\nn = int(input())\nprint(\"простое\" if is_prime(n) else \"составное\")", "tests": [["7", "простое"], ["12", "составное"], ["2", "простое"], ["97", "простое"], ["91", "составное"]]}, {"lv": 3, "title": "Сумма цифр через функцию", "t": "Опишите функцию digit_sum(n). Введите n и выведите сумму цифр всех чисел от 1 до n.", "start": "def digit_sum(n):\n    # допишите\n    pass\n\nn = int(input())\n", "sol": "def digit_sum(n):\n    s = 0\n    while n > 0:\n        s += n % 10\n        n //= 10\n    return s\n\nn = int(input())\ntotal = 0\nfor i in range(1, n + 1):\n    total += digit_sum(i)\nprint(total)", "tests": [["9", "45"], ["10", "46"], ["100", "901"]]}], "brute": [{"lv": 1, "title": "Трёхзначные числа", "t": "Выведите, сколько трёхзначных чисел имеют сумму цифр, равную 10. (Ввода нет.)", "start": "# перебирайте числа от 100 до 999\n", "sol": "k = 0\nfor n in range(100, 1000):\n    if n // 100 + n // 10 % 10 + n % 10 == 10:\n        k += 1\nprint(k)", "tests": [["", "54"]]}, {"lv": 2, "title": "Пифагоровы тройки", "t": "Введено n. Выведите, сколько троек натуральных a < b < c ≤ n удовлетворяют a² + b² = c².", "start": "n = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nk = 0\nfor a in range(1, n + 1):\n    for b in range(a + 1, n + 1):\n        for c in range(b + 1, n + 1):\n            if a * a + b * b == c * c:\n                k += 1\nprint(k)", "tests": [["5", "1"], ["20", "6"], ["50", "20"]]}, {"lv": 3, "title": "Делители", "t": "Введено n. Выведите, сколько у него делителей (включая 1 и само n).", "start": "n = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nk = 0\nfor d in range(1, n + 1):\n    if n % d == 0:\n        k += 1\nprint(k)", "tests": [["12", "6"], ["7", "2"], ["100", "9"], ["36", "9"]]}], "base": [{"lv": 1, "title": "Единицы в двоичной записи", "t": "Введено натуральное n. Выведите, сколько единиц в его двоичной записи (делите на 2 с остатком).", "start": "n = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nk = 0\nwhile n > 0:\n    k += n % 2\n    n //= 2\nprint(k)", "tests": [["5", "2"], ["255", "8"], ["8", "1"], ["1023", "10"]]}, {"lv": 2, "title": "Число в системе с основанием k", "t": "Введены n и k (2 ≤ k ≤ 9). Выведите запись числа n в k-ичной системе.", "start": "n = int(input())\nk = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nk = int(input())\ns = \"\"\nwhile n > 0:\n    s = str(n % k) + s\n    n //= k\nprint(s)", "tests": [["10\n2", "1010"], ["100\n7", "202"], ["25\n5", "100"], ["8\n8", "10"]]}, {"lv": 3, "title": "Сколько цифр в записи", "t": "Введены n и k (2 ≤ k ≤ 9). Выведите количество цифр числа n в k-ичной записи.", "start": "n = int(input())\nk = int(input())\n# Напишите решение под этой строкой\n", "sol": "n = int(input())\nk = int(input())\nc = 0\nwhile n > 0:\n    c += 1\n    n //= k\nprint(c)", "tests": [["10\n2", "4"], ["255\n16", "2"], ["100\n3", "5"]]}], "model": [{"lv": 1, "title": "Вклад в банке", "t": "Вводятся сумма вклада, процент в год и число лет. Выведите итоговую сумму (сложные проценты), округлив до копеек.", "start": "s = float(input())\np = float(input())\nyears = int(input())\n# Напишите решение под этой строкой\n", "sol": "s = float(input())\np = float(input())\nyears = int(input())\nfor i in range(years):\n    s = s * (1 + p / 100)\nprint(round(s, 2))", "tests": [["1000\n10\n2", "1210.0"], ["5000\n7.5\n3", "6211.48"], ["100\n5\n0", "100.0"]]}, {"lv": 2, "title": "Падение тела", "t": "Тело падает с высоты h метров без начальной скорости (g = 9,8 м/с²). Выведите время падения, округлив до сотых: t = √(2h/g).", "start": "h = float(input())\n# Напишите решение под этой строкой\n", "sol": "h = float(input())\nprint(round((2 * h / 9.8) ** 0.5, 2))", "tests": [["19.6", "2.0"], ["100", "4.52"], ["4.9", "1.0"]]}, {"lv": 3, "title": "Рост популяции", "t": "Численность растёт на p % в год. Вводятся начальная численность n, p и предел m. Выведите, через сколько лет численность впервые достигнет m или превысит.", "start": "n = float(input())\np = float(input())\nm = float(input())\n# Напишите решение под этой строкой\n", "sol": "n = float(input())\np = float(input())\nm = float(input())\nyears = 0\nwhile n < m:\n    n = n * (1 + p / 100)\n    years += 1\nprint(years)", "tests": [["100\n10\n200", "8"], ["1000\n5\n1000", "0"], ["10\n100\n100", "4"]]}]};
